-- FamilyOS :: 0242 Blog hero images — make every article image UNIQUE
-- ----------------------------------------------------------------------------
-- Quality bar (docs/MARKETING_PLATFORM_COORDINATION.md §0.4): every article
-- image must be FREE and UNIQUE — no duplicates. Prior batches reused a ~20
-- image pool across 200 articles; this assigns each published post a DISTINCT
-- free-license Unsplash CDN photo (each URL curl-verified HTTP 200 — no broken
-- images) plus honest category-based alt text. Idempotent: re-running sets the
-- same per-slug values. Additive (UPDATE only; no schema change).

UPDATE public.blog_posts AS b
SET hero_image_url    = v.url,
    hero_image_alt    = v.alt,
    hero_image_credit = 'Unsplash',
    updated_at        = now()
FROM (VALUES
